// TlsMode `verify` — a certificate chaining to a public root.
//
// `trust-on-first-use` — pin whatever the controller presents now and refuse a
// change later. **Controllers ship self-signed certificates**, and every shipped
// integration answers that by disabling verification entirely: PacketFence sets
// `verify_hostname => 0`, TP-Link's own sample sets `CURLOPT_SSL_VERIFYPEER =
// FALSE`. Foyer will not offer that. Pinning is the same one-click experience
// for the operator and is not silently equivalent to no TLS at all — a form
// with no TLS choice fails on first contact for most deployments, and a form
// whose only choice is "ignore certificates" teaches the wrong habit on a box
// holding a network's credentials.
type TlsMode string

// TrendBucket defines model for TrendBucket.
type TrendBucket struct {
	// Bytes `inputOctetsTotal + outputOctetsTotal` over the accounting sessions that
	// **started** in the bucket. `radacct` keeps a session's latest counter and
	// no history, so a session is attributed whole to the bucket it began in;
	// a guest who stayed past midnight is counted on the day they arrived.
	//
	// Sessions that never reported a counter contribute nothing, and on the
	// controller-API path there is no accounting at all — so this is a floor on
	// the bytes the venue carried, never a meter of them.
	Bytes int64 `json:"bytes"`

	// BytesFreshness `Metric`'s three clauses, over the rows this bucket's `bytes` counts that
	// are **still open** — a closed session's counter is its final report and
	// has no sample age. No open row → `live`, dated now. Otherwise `sampledAt`
	// is the oldest `lastUpdateAt` (or `startedAt`) among them, `intervalSeconds`
	// is the 300-second floor, and `stale` past twice that. An orphaned session
	// keeps its bucket `stale` until it is reaped, which is true.
	BytesFreshness Freshness `json:"bytesFreshness"`

	// BytesLowerBound At least one counted session has `countersWrapped`, so its total is a
	// lower bound (see `Session.inputOctetsTotal`) and so is this. Render it as
	// "at least".
	BytesLowerBound bool `json:"bytesLowerBound"`

	// End Exclusive.
	End time.Time `json:"end"`

	// GuestDevices **Distinct client devices, not people.** A MAC counts once per bucket if
	// it started an accounting session or was granted through the portal in
	// it — the union, because the controller-API path leaves grants and no
	// accounting while an 802.1X network leaves accounting and no grants.
	// A phone presenting a private address per SSID is one device per SSID,
	// and a phone that rotated its address mid-week is two in that week.
	GuestDevices int       `json:"guestDevices"`
	Start        time.Time `json:"start"`

	// VouchersRedeemed Vouchers whose `firstUsedAt` falls in the bucket — the rule
	// `vouchersRedeemedToday` counts by, over a longer window. A table nobody
	// has to sample, so it carries no freshness.
	VouchersRedeemed int `json:"vouchersRedeemed"`
}

// TrendGranularity defines model for TrendGranularity.
type TrendGranularity string

// Trends Per-bucket totals over `[buckets[0].start, buckets[-1].end)`, oldest first,
// with **every bucket present** — a day nothing happened on is a zero, and a
// missing bar would read as a day nobody measured.
type Trends struct {
	Buckets     []TrendBucket    `json:"buckets"`
	Granularity TrendGranularity `json:"granularity"`
}

